var selector = element.querySelector('iron-selector#chips');
if (!selector) return;

var existingChips = selector.querySelectorAll('yt-chip-cloud-chip-renderer');
if (existingChips.length < 2) return;

var unwatchedChip = existingChips[1];
if (!unwatchedChip) return;

var chipTexts = [];
for (var i = 0; i < existingChips.length; i++) {
  var div = existingChips[i].querySelector('chip-shape .ytChipShapeChip > div');
  if (div) chipTexts.push(div.textContent);
}
if (chipTexts.indexOf('Shorts only') !== -1) return;

var newChip = document.createElement('yt-chip-cloud-chip-renderer');
newChip.setAttribute('class', 'style-scope yt-chip-cloud-chip-renderer');
newChip.setAttribute('chip-style', 'STYLE_HOME_FILTER');

var chipShapeContainer = document.createElement('div');
chipShapeContainer.id = 'chip-shape-container';
chipShapeContainer.setAttribute('class', 'style-scope yt-chip-cloud-chip-renderer');

var chipShape = document.createElement('chip-shape');
chipShape.setAttribute('class', 'ytChipShapeHost');

var button = document.createElement('button');
button.className = 'ytChipShapeButtonReset';
button.setAttribute('role', 'tab');
button.setAttribute('aria-selected', 'false');

var chipDiv = document.createElement('div');
chipDiv.className = 'ytChipShapeChip ytChipShapeInactive ytChipShapeOnlyTextPadding';

var textDiv = document.createElement('div');
textDiv.textContent = 'Shorts only';

chipDiv.appendChild(textDiv);
button.appendChild(chipDiv);
chipShape.appendChild(button);
chipShapeContainer.appendChild(chipShape);
newChip.appendChild(chipShapeContainer);

selector.insertBefore(newChip, unwatchedChip.nextSibling);

var contents = element.querySelector('#contents');
if (!contents) return;

var children = Array.from(contents.children);
var firstShortsShelf = null;

for (var i = 0; i < children.length; i++) {
  var child = children[i];
  if (child.tagName === 'GRID-SHELF-VIEW-MODEL' || child.classList.contains('ytGridShelfViewModelHost')) {
    firstShortsShelf = child;
    break;
  }
}

if (!firstShortsShelf) return;

var firstChild = contents.firstChild;
if (firstChild === firstShortsShelf) return;

contents.insertBefore(firstShortsShelf, firstChild);

